### Tailwind CSS Configuration

The Tailwind config maps `core-theme.css` semantic tokens to Tailwind utility classes. Use `var(--token)` directly (not `hsl(var(--token))` — `core-theme.css` uses hex values, not HSL channels):

```typescript
// tailwind.config.ts
import type { Config } from 'tailwindcss';

const config: Config = {
  darkMode: ['class'],   // CSS class-based: .theme-dark / .theme-light on container
  content: ['./src/**/*.{ts,tsx}', './app/**/*.{ts,tsx}'],
  theme: {
    extend: {
      colors: {
        // Map to core-theme.css semantic tokens
        'text-primary':         'var(--text-primary)',
        'text-secondary':       'var(--text-secondary)',
        'text-inverse':         'var(--text-inverse)',
        'text-error':           'var(--text-error)',
        'text-success':         'var(--text-success)',
        'text-accent':          'var(--text-accent)',
        'bg-primary':           'var(--background-primary)',
        'bg-secondary':         'var(--background-secondary)',
        'bg-accent':            'var(--background-accent)',
        'btn-primary':          'var(--button-bg-primary)',
        'btn-primary-hover':    'var(--button-bg-primary-hover)',
        'icon-primary':         'var(--icon-color-primary)',
        'icon-error':           'var(--icon-color-error)',
        'link':                 'var(--link-color)',
        'link-hover':           'var(--link-hover)',
      },
      borderRadius: {
        base: 'var(--border-radius-base)',
        lg:   'var(--border-radius-lg)',
        xlg:  'var(--border-radius-xlg)',
      },
      fontFamily: {
        sans: ['Arial', '"Helvetica Neue"', 'Helvetica', 'sans-serif'],
        heading: ['"Poppins Bold"', 'Arial', 'Helvetica', 'sans-serif'],
        mono: ['monospace'],
      },
      fontSize: {
        xs:    'var(--font-size-xsmall)',
        sm:    'var(--font-size-small)',
        base:  'var(--font-size-regular)',
        lg:    'var(--font-size-large)',
        xl:    'var(--font-size-xlarge)',
        '2xl': 'var(--font-size-xxlarge)',
      },
      spacing: {
        xs:  'var(--spacing-xs)',
        sm:  'var(--spacing-sm)',
        md:  'var(--spacing-md)',
        lg:  'var(--spacing-lg)',
        xl:  'var(--spacing-xl)',
        xxl: 'var(--spacing-xxl)',
      },
    },
  },
};

export default config;
```

